INSERT INTO products (id, sku, slug, name, description, kind, active, images, sort_order, created_at, updated_at, details, features) VALUES ('98b093b1-55d4-4495-ac21-934bb6ed98cb', NULL, 'skyball-racket-pro', 'SkyBall Racket Pro', 'Our premium One-Piece Carbon Forward unibody construction racket, delivering a pure, crisp feel on every shot.', 'base', TRUE, '["https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/racquet_pro_1.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/racquet_pro_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_racquet_pro_3.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/racket_in_bag.png?0"]'::jsonb, 31, '2025-12-30T16:33:40.114153+00:00', '2026-02-04T00:44:30.315221+00:00', 'The SkyBall Pro Carbon is engineered for the competitive player who demands absolute control. At just 180g, it is ultra-lightweight, allowing for lightning-fast hand speed during rapid-fire exchanges at the net. The compact 76 sq. inch head size is designed for the sharpshooter—prioritizing directional control and placement over raw power. This is a high-performance 21-inch adult instrument, not a toy.
