INSERT INTO products (id, sku, slug, name, description, kind, active, images, sort_order, created_at, updated_at, details, features) VALUES ('df3bb11e-a97d-428d-8a91-f1b9aba58f16', NULL, 'anywhere-kit-starter', 'Anywhere Kit – Starter', 'Everything you need to play SkyBall anywhere! Four Starter Rackets, Two SkyBall 3-packs, and a portable SkyBall net.', 'bundle', TRUE, '["https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/anywhere_kit_1.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/anywhere_kit_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_racquet_3.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/racquet_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/ball_3pack_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/racket_in_bag.png?0", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/skyball_anywhere_grass.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/skyball_anywhere_nj.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/net-1.JPG", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/ballinsky.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/skyball_anywhere_central_park.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/orange_ball_sq_bg.jpg"]'::jsonb, 22, '2025-12-30T16:33:40.114153+00:00', '2026-07-28T17:51:20.287111+00:00', 'Take the game to the driveway, the street, or the beach lot. The SkyBall™ Anywhere Kit gives you total freedom to play whenever and wherever you want. Our specialized SkyBalls are designed to bounce on turf, asphalt, concrete, and just about any surface, while the portable net system sets up in minutes to create an instant regulation-height barrier.
INSERT INTO products (id, sku, slug, name, description, kind, active, images, sort_order, created_at, updated_at, details, features) VALUES ('b8111aff-404f-47ab-aa79-2dacfd0c0710', NULL, 'anywhere-kit-pro', 'Anywhere Kit – Pro', 'Everything you need to play SkyBall anywhere! Four Pro Rackets, Two SkyBall 3-packs, and a portable SkyBall net.', 'bundle', TRUE, '["https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/anywhere_pro_1.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/anywhere_pro_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/racquet_pro_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_racquet_pro_3.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/ball_3pack_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/racket_in_bag.png?0", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/skyball_anywhere_grass.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/net-1.JPG", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/skyball_anywhere_nj.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/ballinsky.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/website-content/skyball_anywhere_central_park.jpeg", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/orange_ball_sq_bg.jpg"]'::jsonb, 12, '2025-12-30T16:33:40.114153+00:00', '2026-02-24T02:08:11.612306+00:00', 'Take the game to the driveway, the street, or the beach lot. The SkyBall™ Anywhere Kit gives you total freedom to play whenever and wherever you want. Our specialized SkyBalls are designed to bounce on turf, asphalt, concrete, and just about any surface, while the portable net system sets up in minutes to create an instant regulation-height barrier.
INSERT INTO products (id, sku, slug, name, description, kind, active, images, sort_order, created_at, updated_at, details, features) VALUES ('1eabd20a-0217-4a02-80da-5f502a5f5945', NULL, 'skyball-12-pack', 'SkyBall 12-Pack', '12 SkyBall™ balls', 'base', TRUE, '["https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_ind_ball_blue_orange.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_ball_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/orange_ball_sq_bg.jpg"]'::jsonb, 23, '2025-12-30T16:33:40.114153+00:00', '2026-03-29T18:12:17.786412+00:00', 'Engineered for the perfect rally, the SkyBall™ features a specialized high-density foam construction, these balls maintain their bounce longer than standard tennis balls and travel at a speed optimized for smaller courts. This allows you to take full, aggressive swings without the ball launching into the next zip code.
INSERT INTO products (id, sku, slug, name, description, kind, active, images, sort_order, created_at, updated_at, details, features) VALUES ('63f6993d-d10f-4197-9ac4-d6340fb51250', NULL, 'skyball-50-pack', 'SkyBall 50-Pack', '50 SkyBall™ balls', 'base', TRUE, '["https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_ind_ball_blue_orange.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_ball_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/orange_ball_sq_bg.jpg"]'::jsonb, 14, '2025-12-30T16:33:40.114153+00:00', '2026-03-29T18:12:04.510747+00:00', 'Engineered for the perfect rally, the SkyBall™ features a specialized high-density foam construction, these balls maintain their bounce longer than standard tennis balls and travel at a speed optimized for smaller courts. This allows you to take full, aggressive swings without the ball launching into the next zip code.
INSERT INTO products (id, sku, slug, name, description, kind, active, images, sort_order, created_at, updated_at, details, features) VALUES ('950a70ba-b3d1-4dde-861f-cb5623dcd262', NULL, 'skyball-racket', 'SkyBall Racket', 'Our standard racket is constructed with a rugged Two-Piece Aluminum frame, it is designed to withstand the rigors of learning while delivering consistent power.', 'base', TRUE, '["https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/racquet_1.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/skyball_racquet_3.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/updated/racquet_2.png", "https://jbcpublicbucket.s3.us-east-1.amazonaws.com/skyball-shop/racket_in_bag.png?0"]'::jsonb, 32, '2025-12-30T16:33:40.114153+00:00', '2026-07-28T17:50:54.726225+00:00', 'We engineered this model with a generous 83 sq. inch head size, creating a massive sweet spot that is forgiving on off-center hits. The slightly heavier 190g weight provides excellent stability and "plow-through," helping you generate deep power from the baseline without over-swinging.
